+/** Organizations with active connections for an integration (aggregated across members). */
+export async function listOpsOrgsForIntegration(
+  integrationId: string,
+): Promise<OpsIntegrationOrgRow[]> {
+  const id = integrationId.trim().toLowerCase();
+  if (!id) return [];
+
+  const rows = await db
+    .select({
+      orgId: userIntegration.orgId,
+      orgName: org.name,
+      orgStatus: org.status,
+      userId: userIntegration.userId,
+      connectedAt: userIntegration.connectedAt,
+    })
+    .from(userIntegration)
+    .innerJoin(org, eq(org.id, userIntegration.orgId))
+    .where(and(eq(userIntegration.integrationId, id), eq(userIntegration.status, "active")));
+
+  type Acc = {
+    orgId: string;
+    orgName: string;
+    orgStatus: string;
+    users: Set<string>;
+    connectionCount: number;
+    lastConnectedAt: Date | null;
+  };
+  const byOrg = new Map<string, Acc>();
+  for (const row of rows) {
+    let acc = byOrg.get(row.orgId);
+    if (!acc) {
+      acc = {
+        orgId: row.orgId,
+        orgName: row.orgName,
+        orgStatus: row.orgStatus,
+        users: new Set(),
+        connectionCount: 0,
+        lastConnectedAt: null,
+      };
+      byOrg.set(row.orgId, acc);
+    }
+    acc.connectionCount += 1;
+    acc.users.add(row.userId);
+    if (!acc.lastConnectedAt || row.connectedAt > acc.lastConnectedAt) {
+      acc.lastConnectedAt = row.connectedAt;
+    }
+  }
+
+  const capabilityId = `connection:${id}`;
+  const capabilityRows = await db
+    .select({
+      userId: capabilityRecord.userId,
+      scopeKey: capabilityRecord.scopeKey,
+      connectedAt: capabilityRecord.updatedAt,
+    })
+    .from(capabilityRecord)
+    .where(
+      and(eq(capabilityRecord.capabilityId, capabilityId), eq(capabilityRecord.status, "active")),
+    );
+  const capabilityUserIds = [
+    ...new Set(capabilityRows.flatMap((row) => (row.userId ? [row.userId] : []))),
+  ];
+  if (capabilityUserIds.length > 0) {
+    const memberships = await db
+      .select({
+        orgId: orgMembership.orgId,
+        orgName: org.name,
+        orgStatus: org.status,
+        userId: orgMembership.userId,
+      })
+      .from(orgMembership)
+      .innerJoin(org, eq(org.id, orgMembership.orgId))
+      .where(inArray(orgMembership.userId, capabilityUserIds));
+    const membershipsByScope = new Map(
+      memberships.map((membership) => [
+        `user:${membership.userId}:org:${membership.orgId}`,
+        membership,
+      ]),
+    );
+    for (const row of capabilityRows) {
+      const membership = membershipsByScope.get(row.scopeKey);
+      if (!membership) continue;
+      let acc = byOrg.get(membership.orgId);
+      if (!acc) {
+        acc = {
+          orgId: membership.orgId,
+          orgName: membership.orgName,
+          orgStatus: membership.orgStatus,
+          users: new Set(),
+          connectionCount: 0,
+          lastConnectedAt: null,
+        };
+        byOrg.set(membership.orgId, acc);
+      }
+      if (!row.userId) continue;
+      if (!acc.lastConnectedAt || row.connectedAt > acc.lastConnectedAt) {
+        acc.lastConnectedAt = row.connectedAt;
+      }
+      if (acc.users.has(row.userId)) continue;
+      acc.connectionCount += 1;
+      acc.users.add(row.userId);
+    }
+  }
+
+  return [...byOrg.values()]
+    .map((acc) => ({
+      orgId: acc.orgId,
+      orgName: acc.orgName,
+      orgStatus: acc.orgStatus,
+      connectionCount: acc.connectionCount,
+      userCount: acc.users.size,
+      lastConnectedAt: acc.lastConnectedAt?.toISOString() ?? null,
+    }))
+    .sort((a, b) => a.orgName.localeCompare(b.orgName));
+}
