    publicClient: z.boolean().optional(),
    extraAuthParams: z.record(z.string(), z.string()).optional(),
    experimentalOrgIds: z.array(z.string().trim().min(1).max(128)).max(500).optional(),
    dcrRegistrationUrl: z.string().trim().url().max(2000).nullable().optional(),
    dcrClientName: z.string().trim().max(200).nullable().optional(),
    dcrLogoUri: z.string().trim().max(2000).nullable().optional(),
    dcrExtraRegistrationParams: z.record(z.string(), z.unknown()).optional(),
    runtimeConfig: z.unknown().optional(),
  })
  .strict();

export type PatchOpsOAuthServiceInput = z.infer<typeof patchOpsOAuthServiceSchema>;
export type PatchOpsOAuthConnectionInput = z.infer<typeof patchOpsOAuthConnectionSchema>;

function asLifecycle(raw: unknown): OpsOAuthLifecycle {
  if (raw === "experimental" || raw === "production" || raw === "disabled") return raw;
  // Unknown/corrupt values should not look "active" in the Ops editor.
  return "disabled";
}

function asStrategy(raw: unknown): OpsOAuthStrategy {
  if (raw === "dcr") return "dcr";
  return "static";
}

function asStringArray(raw: unknown): string[] {
  if (!Array.isArray(raw)) return [];
  return raw.map((item) => String(item)).filter((item) => item.length > 0);
}

function asStringRecord(raw: unknown): Record<string, string> {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return {};
  return Object.fromEntries(
    Object.entries(raw as Record<string, unknown>).map(([key, value]) => [key, String(value)]),
  );
}

function dateToIso(raw: unknown): string | null {
  if (raw == null) return null;
  if (raw instanceof Date) return raw.toISOString();
  const text = String(raw).trim();
  return text || null;
}

/** Strip secrets before any Ops UI response. */
export function redactOpsOAuthConnection(connection: AuthOAuthConnection): OpsOAuthConnectionView {
  const secret =
    typeof connection.client_secret === "string" ? connection.client_secret.trim() : "";
  return {
    service: connection.service,
    credentialStrategy: asStrategy(connection.credential_strategy),
    lifecycleStatus: asLifecycle(connection.lifecycle_status),
    handlerKind: connection.handler_kind || "generic",
    clientId: connection.client_id ?? "",
    clientSecretConfigured: secret.length > 0,
    authUrl: connection.auth_url ?? "",
    tokenUrl: connection.token_url ?? "",
    userInfoUrl: connection.user_info_url?.trim() || null,
    defaultScopes: asStringArray(connection.default_scopes),
    defaultUserScopes: asStringArray(connection.default_user_scopes),
    allowedScopes: asStringArray(connection.allowed_scopes),
    scopeDelimiter: connection.scope_delimiter ?? " ",
    scopeParam: connection.scope_param ?? "scope",
    tokenAccessPath: connection.token_access_path?.trim() || null,
    pkce: Boolean(connection.pkce),
    publicClient: Boolean(connection.public_client),
    extraAuthParams: asStringRecord(connection.extra_auth_params),
    experimentalOrgIds: asStringArray(connection.experimental_org_ids),
    dcrRegistrationUrl: connection.dcr_registration_url?.trim() || null,
    dcrClientName: connection.dcr_client_name?.trim() || null,
    dcrLogoUri: connection.dcr_logo_uri?.trim() || null,
    dcrExtraRegistrationParams:
      connection.dcr_extra_registration_params &&
      typeof connection.dcr_extra_registration_params === "object" &&
      !Array.isArray(connection.dcr_extra_registration_params)
        ? connection.dcr_extra_registration_params
        : {},
    dcrRegisteredAt: dateToIso(connection.dcr_registered_at),
    runtimeConfig: connection.runtime_config ?? {},
    version: typeof connection.version === "number" ? connection.version : 0,
    disabledAt: dateToIso(connection.disabled_at),
  };
}

function connectionPatchToAuthBody(input: PatchOpsOAuthConnectionInput): Record<string, unknown> {
  const body: Record<string, unknown> = {};
  if (input.lifecycleStatus !== undefined) body.lifecycle_status = input.lifecycleStatus;
  if (input.handlerKind !== undefined) body.handler_kind = input.handlerKind;
  if (input.clientId !== undefined) body.client_id = input.clientId;
  if (input.clientSecret !== undefined && input.clientSecret.trim().length > 0) {
    body.client_secret = input.clientSecret;
  }
  if (input.authUrl !== undefined) body.auth_url = input.authUrl;
  if (input.tokenUrl !== undefined) body.token_url = input.tokenUrl;
  if (input.userInfoUrl !== undefined) body.user_info_url = input.userInfoUrl;
  if (input.defaultScopes !== undefined) body.default_scopes = input.defaultScopes;
  if (input.defaultUserScopes !== undefined) body.default_user_scopes = input.defaultUserScopes;
  if (input.allowedScopes !== undefined) body.allowed_scopes = input.allowedScopes;
  if (input.scopeDelimiter !== undefined) body.scope_delimiter = input.scopeDelimiter;
  if (input.scopeParam !== undefined) body.scope_param = input.scopeParam;
  if (input.tokenAccessPath !== undefined) body.token_access_path = input.tokenAccessPath;
  if (input.pkce !== undefined) body.pkce = input.pkce;
  if (input.publicClient !== undefined) body.public_client = input.publicClient;
  if (input.extraAuthParams !== undefined) body.extra_auth_params = input.extraAuthParams;
  if (input.experimentalOrgIds !== undefined) {
    body.experimental_org_ids = input.experimentalOrgIds;
  }
  if (input.dcrRegistrationUrl !== undefined) {
    body.dcr_registration_url = input.dcrRegistrationUrl;
  }
  if (input.dcrClientName !== undefined) body.dcr_client_name = input.dcrClientName;
  if (input.dcrLogoUri !== undefined) body.dcr_logo_uri = input.dcrLogoUri;
  if (input.dcrExtraRegistrationParams !== undefined) {
    body.dcr_extra_registration_params = input.dcrExtraRegistrationParams;
  }
  if (input.runtimeConfig !== undefined) body.runtime_config = input.runtimeConfig;
  return body;
}

function servicePatchToAuthBody(input: PatchOpsOAuthServiceInput): Record<string, unknown> {
  const body: Record<string, unknown> = {};
  if (input.name !== undefined) body.name = input.name;
  if (input.description !== undefined) body.description = input.description;
  if (input.category !== undefined) body.category = input.category;
  if (input.logo !== undefined) body.logo = input.logo;
  return body;
}

export async function listOpsOAuthRegistry(): Promise<OpsOAuthServiceSummary[]> {
  const services = await genesisAuthAdminRequest<AuthOAuthService[]>(
    "GET",
    "/internal/genesis/oauth/services",
    { failureLabel: "list OAuth services" },
  );
  const rows = await Promise.all(
    services.map(async (service) => {
      const connections = await genesisAuthAdminRequest<AuthOAuthConnection[]>(
        "GET",
        `/internal/genesis/oauth/services/${encodeURIComponent(service.service)}/connections`,
        { failureLabel: `list OAuth connections for ${service.service}` },
      );
      return {
        service: service.service,
        name: service.name,
        description: service.description,
        category: service.category,
        logo: service.logo?.trim() || null,
        connections: connections.map((connection) => {
          const redacted = redactOpsOAuthConnection(connection);
          return {
            credentialStrategy: redacted.credentialStrategy,
            lifecycleStatus: redacted.lifecycleStatus,
            handlerKind: redacted.handlerKind,
            experimentalOrgCount: redacted.experimentalOrgIds.length,
            clientSecretConfigured: redacted.clientSecretConfigured,
          };
        }),
      } satisfies OpsOAuthServiceSummary;
    }),
  );
  return rows.sort((a, b) => a.service.localeCompare(b.service));
}

export async function getOpsOAuthService(service: string): Promise<OpsOAuthServiceDetail | null> {
  const slug = service.trim().toLowerCase();
  if (!slug) return null;
  try {
    const [svc, connections] = await Promise.all([
      genesisAuthAdminRequest<AuthOAuthService>(
        "GET",
        `/internal/genesis/oauth/services/${encodeURIComponent(slug)}`,
        { failureLabel: `get OAuth service ${slug}` },
      ),
      genesisAuthAdminRequest<AuthOAuthConnection[]>(
        "GET",
        `/internal/genesis/oauth/services/${encodeURIComponent(slug)}/connections`,
        { failureLabel: `list OAuth connections for ${slug}` },
      ),
    ]);
    return {
      service: svc.service,
      name: svc.name,
      description: svc.description,
      category: svc.category,
      logo: svc.logo?.trim() || null,
      connections: connections.map(redactOpsOAuthConnection),
    };
  } catch (error) {
    if (error instanceof GenesisAuthAdminError && error.status === 404) return null;
    throw error;
  }
}

export async function patchOpsOAuthService(
  service: string,
  input: PatchOpsOAuthServiceInput,
): Promise<OpsOAuthServiceDetail> {
  const slug = service.trim().toLowerCase();
  const body = servicePatchToAuthBody(input);
  if (Object.keys(body).length === 0) {
    const current = await getOpsOAuthService(slug);
    if (!current) throw new GenesisAuthAdminError("service not found", 404);
    return current;
  }
  await genesisAuthAdminRequest<AuthOAuthService>(
    "PATCH",
    `/internal/genesis/oauth/services/${encodeURIComponent(slug)}`,
    { body, failureLabel: `patch OAuth service ${slug}` },
  );
  const detail = await getOpsOAuthService(slug);
  if (!detail) throw new GenesisAuthAdminError("service not found", 404);
  return detail;
}

export async function patchOpsOAuthConnection(
  service: string,
  strategy: string,
  input: PatchOpsOAuthConnectionInput,
): Promise<OpsOAuthConnectionView> {
  const slug = service.trim().toLowerCase();
  const parsedStrategy = strategySchema.safeParse(strategy.trim().toLowerCase());
  if (!parsedStrategy.success) {
    throw new GenesisAuthAdminError("credential strategy must be static or dcr", 400);
  }
  const credentialStrategy = parsedStrategy.data;
  const body = connectionPatchToAuthBody(input);
  if (Object.keys(body).length === 0) {
    const current = await getOpsOAuthService(slug);
    const connection = current?.connections.find(
      (row) => row.credentialStrategy === credentialStrategy,
    );
    if (!connection) throw new GenesisAuthAdminError("connection not found", 404);
    return connection;
  }
  await genesisAuthAdminRequest<AuthOAuthConnection>(
    "PATCH",
    `/internal/genesis/oauth/services/${encodeURIComponent(slug)}/connections/${encodeURIComponent(credentialStrategy)}`,
    { body, failureLabel: `patch OAuth connection ${slug}/${credentialStrategy}` },
  );
  const detail = await getOpsOAuthService(slug);
  const connection = detail?.connections.find(
    (row) => row.credentialStrategy === credentialStrategy,
  );
  if (!connection) throw new GenesisAuthAdminError("connection not found", 404);
  return connection;
}

export function opsOAuthAdminErrorStatus(error: unknown): number {
  if (error instanceof GenesisAuthAdminError) {
    if (error.status >= 400 && error.status < 600) return error.status;
  }
  return 502;
}

export function opsOAuthAdminErrorMessage(error: unknown, fallback: string): string {
  if (error instanceof GenesisAuthAdminError) {
    const message = error.message.trim();
    if (message) return message;
  }
  if (error instanceof Error && error.message.trim()) return error.message.trim();
  return fallback;
}

