    dcrRegistrationUrl: form.dcrRegistrationUrl.trim() ? form.dcrRegistrationUrl.trim() : null,
    dcrClientName: form.dcrClientName.trim() ? form.dcrClientName.trim() : null,
    dcrLogoUri: form.dcrLogoUri.trim() ? form.dcrLogoUri.trim() : null,
    dcrExtraRegistrationParams: dcrExtra,
    runtimeConfig,
  };
}

/** Confirm before promoting to production or soft-disabling. */
export function lifecycleRequiresConfirmation(
  current: OpsOAuthLifecycle,
  next: OpsOAuthLifecycle,
): boolean {
  if (next === current) return false;
  return next === "production" || next === "disabled";
}

export function filterOpsOAuthServices(
  services: OpsOAuthServiceSummary[],
  query: string,
): OpsOAuthServiceSummary[] {
  const q = query.trim().toLowerCase();
  if (!q) return services;
  return services.filter((service) => {
    const haystack = [
      service.service,
      service.name,
      service.description,
      service.category,
      ...service.connections.map((c) => c.lifecycleStatus),
      ...service.connections.map((c) => c.handlerKind),
    ]
      .join(" ")
      .toLowerCase();
    return haystack.includes(q);
  });
}

export function formatOpsOAuthLoadError(body: { error?: string } | null, fallback: string): string {
  const message = body?.error?.trim();
  return message || fallback;
}

