} from "@web/components/settings/settings-section";
import { apiFetch } from "@web/lib/api-fetch";
import { ArrowLeft, Building2, Info, KeyRound, Loader2, Plug, RotateCcw } from "lucide-react";
import { type ReactNode, useCallback, useEffect, useState } from "react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Skeleton } from "@/components/ui/skeleton";
import { Textarea } from "@/components/ui/textarea";
import { OpsIntegrationAllowlist } from "./ops-integration-allowlist";
import { OpsIntegrationOrgsPanel } from "./ops-integration-orgs-panel";
import {
  buildConnectionPayload,
  buildServicePayload,
  connectionToForm,
  formatOpsOAuthLoadError,
  isFormDirty,
  lifecycleRequiresConfirmation,
  OPS_OAUTH_CATEGORIES,
  OPS_OAUTH_HANDLER_KINDS,
  OPS_OAUTH_LIFECYCLES,
  type OpsOAuthConnectionDetail,
  type OpsOAuthConnectionFormState,
  type OpsOAuthLifecycle,
  type OpsOAuthServiceDetail,
  type OpsOAuthServiceFormState,
  type OpsOAuthStrategy,
  serviceToForm,
  strategyLabel,
} from "./ops-integrations-form";
import { LifecycleBadge } from "./ops-integrations-lifecycle";

function Field({
  label,
  htmlFor,
  hint,
  className,
  children,
}: {
  label: string;
  htmlFor?: string;
  hint?: ReactNode;
  className?: string;
  children: ReactNode;
}) {
  return (
    <div className={className ? `space-y-1.5 ${className}` : "space-y-1.5"}>
      <Label htmlFor={htmlFor}>{label}</Label>
      {children}
      {hint ? <p className="text-xs text-muted-foreground">{hint}</p> : null}
    </div>
  );
}

function Card({
  title,
  description,
  action,
  children,
}: {
  title: string;
  description?: string;
  action?: ReactNode;
  children: ReactNode;
}) {
  return (
    <section className={settingsCardClassName}>
      <SettingsPanelHeader title={title} description={description} action={action} />
      <div className={settingsCardBodyClassName}>{children}</div>
    </section>
  );
}

function ServicePanel({
  form,
  onChange,
  onSave,
  saving,
  dirty,
  onReset,
}: {
  form: OpsOAuthServiceFormState;
  onChange: (next: OpsOAuthServiceFormState) => void;
  onSave: () => void;
  saving: boolean;
  dirty: boolean;
  onReset: () => void;
}) {
  return (
    <Card
      title="Service metadata"
      description="How this provider is presented in the Genesis integrations catalog."
    >
      <div className="space-y-4">
        <div className="grid gap-4 sm:grid-cols-2">
          <Field label="Name" htmlFor="ops-oauth-name">
            <Input
              id="ops-oauth-name"
              value={form.name}
              onChange={(event) => onChange({ ...form, name: event.target.value })}
            />
          </Field>
          <Field label="Category" htmlFor="ops-oauth-category">
            <Select
              value={form.category}
              onValueChange={(category) => onChange({ ...form, category })}
            >
              <SelectTrigger id="ops-oauth-category" className="w-full">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {[...new Set([form.category, ...OPS_OAUTH_CATEGORIES])].map((category) => (
                  <SelectItem key={category} value={category}>
                    {category}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </Field>
        </div>
        <Field
          label="Description"
          htmlFor="ops-oauth-description"
          hint={`${form.description.trim().length}/280 characters`}
        >
          <Textarea
            id="ops-oauth-description"
            value={form.description}
            onChange={(event) => onChange({ ...form, description: event.target.value })}
            rows={3}
          />
        </Field>
        <Field
          label="Logo"
          htmlFor="ops-oauth-logo"
          hint="Data URI or absolute URL. Leave blank to fall back to the default icon."
        >
          <div className="flex items-start gap-3">
            {form.logo.trim() ? (
              <img
                src={form.logo.trim()}
                alt=""
                className="size-10 shrink-0 rounded-md border border-border bg-background object-contain p-1"
              />
            ) : null}
            <Textarea
              id="ops-oauth-logo"
              value={form.logo}
              onChange={(event) => onChange({ ...form, logo: event.target.value })}
              rows={2}
              className="max-h-24 overflow-auto font-mono text-xs"

