          </div>
        </Field>
        <SaveBar
          dirty={dirty}
          saving={saving}
          onReset={onReset}
          onSave={onSave}
          saveLabel="Save service"
        />
      </div>
    </Card>
  );
}

function SaveBar({
  dirty,
  saving,
  onReset,
  onSave,
  saveLabel,
}: {
  dirty: boolean;
  saving: boolean;
  onReset: () => void;
  onSave: () => void;
  saveLabel: string;
}) {
  return (
    <div className="flex flex-wrap items-center justify-end gap-2 border-t border-sidebar-border/50 pt-4">
      <span className="mr-auto text-xs text-muted-foreground">
        {dirty ? "Unsaved changes" : "All changes saved"}
      </span>
      <Button type="button" variant="ghost" size="sm" disabled={!dirty || saving} onClick={onReset}>
        <RotateCcw className="size-3.5" />
        Discard
      </Button>
      <Button type="button" size="sm" disabled={!dirty || saving} onClick={onSave}>
        {saving ? <Loader2 className="size-4 animate-spin" /> : null}
        {saveLabel}
      </Button>
    </div>
  );
}

function ScopeList({
  label,
  htmlFor,
  value,
  onChange,
}: {
  label: string;
  htmlFor: string;
  value: string;
  onChange: (value: string) => void;
}) {
  const count = value.split(/[\n,]/).filter((item) => item.trim()).length;
  return (
    <Field label={label} htmlFor={htmlFor} hint={`${count} scope${count === 1 ? "" : "s"}`}>
      <Textarea
        id={htmlFor}
        value={value}
        onChange={(event) => onChange(event.target.value)}
        rows={6}
        placeholder="one per line"
        className="font-mono text-xs"
      />
    </Field>
  );
}

