/** Client-safe API-key catalog ids (no server/db imports). */
export const API_KEY_INTEGRATION_IDS = ["shopmonkey", "callrail"] as const;

export type ApiKeyIntegrationId = (typeof API_KEY_INTEGRATION_IDS)[number];

export function isApiKeyIntegrationId(integrationId: string): boolean {
  const normalized = integrationId.trim().toLowerCase();
  return (API_KEY_INTEGRATION_IDS as readonly string[]).includes(normalized);
}

