  defaultUserScopes: [],
  allowedScopes: ["openid", "offline_access", "accounting.contacts"],
  scopeDelimiter: " ",
  scopeParam: "scope",
  tokenAccessPath: null,
  pkce: false,
  publicClient: false,
  extraAuthParams: { prompt: "consent" },
  experimentalOrgIds: ["org_a", "org_b"],
  dcrRegistrationUrl: null,
  dcrClientName: null,
  dcrLogoUri: null,
  dcrExtraRegistrationParams: {},
  runtimeConfig: { tenant: true },
  version: 3,
};

describe("ops integrations form helpers", () => {
  test("filters the searchable provider list", () => {
    const services = [
      {
        service: "xero",
        name: "Xero",
        description: "Accounting",
        category: "finance",
        logo: null,
        connections: [
          {
            credentialStrategy: "static" as const,
            lifecycleStatus: "experimental" as const,
            handlerKind: "xero",
            experimentalOrgCount: 2,
            clientSecretConfigured: true,
          },
        ],
      },
      {
        service: "wave",
        name: "Wave",
        description: "Invoices",
        category: "finance",
        logo: null,
        connections: [
          {
            credentialStrategy: "static" as const,
            lifecycleStatus: "production" as const,
            handlerKind: "wave",
            experimentalOrgCount: 0,
            clientSecretConfigured: false,
          },
        ],
      },
    ];
    expect(filterOpsOAuthServices(services, "xero")).toHaveLength(1);
    expect(filterOpsOAuthServices(services, "production")[0]?.service).toBe("wave");
    expect(filterOpsOAuthServices(services, "finance")).toHaveLength(2);
  });

  test("connectionToForm keeps secrets write-only (empty)", () => {
    const form = connectionToForm(sampleConnection);
    expect(form.clientSecret).toBe("");
    expect(form.defaultScopesText).toContain("openid");
    expect(form.experimentalOrgIdsText.split("\n")).toEqual(["org_a", "org_b"]);
  });

  test("buildConnectionPayload omits blank clientSecret and includes scopes/allowlist", () => {
    const form = connectionToForm(sampleConnection);
    form.clientSecret = "   ";
    form.defaultScopesText = "openid\noffline_access";
    form.experimentalOrgIdsText = "org_preview, org_local";
    form.lifecycleStatus = "disabled";
    const payload = buildConnectionPayload(form);
    expect(payload).not.toHaveProperty("clientSecret");
    expect(payload.lifecycleStatus).toBe("disabled");
    expect(payload.defaultScopes).toEqual(["openid", "offline_access"]);
    expect(payload.experimentalOrgIds).toEqual(["org_preview", "org_local"]);
    expect(payload.allowedScopes).toEqual(["openid", "offline_access", "accounting.contacts"]);
  });

  test("buildConnectionPayload includes a non-empty clientSecret", () => {
    const form = connectionToForm(sampleConnection);
    form.clientSecret = "NEW_CLIENT_SECRET_VALUE_FOR_TEST";
    const payload = buildConnectionPayload(form);
    expect(payload.clientSecret).toBe("NEW_CLIENT_SECRET_VALUE_FOR_TEST");
  });

  test("requires confirmation for production and disabled only", () => {
    expect(lifecycleRequiresConfirmation("experimental", "production")).toBe(true);
    expect(lifecycleRequiresConfirmation("experimental", "disabled")).toBe(true);
    expect(lifecycleRequiresConfirmation("production", "experimental")).toBe(false);
    expect(lifecycleRequiresConfirmation("disabled", "disabled")).toBe(false);
  });

  test("surfaces API failure messages without inventing secrets", () => {
    expect(formatOpsOAuthLoadError({ error: "auth admin unavailable" }, "fallback")).toBe(
      "auth admin unavailable",
    );
    expect(formatOpsOAuthLoadError({}, "Failed to load integrations")).toBe(
      "Failed to load integrations",
    );
    expect(formatOpsOAuthLoadError({ error: "bad" }, "x")).not.toContain("client_secret");
  });

  test("tracks dirty state so Save stays disabled until something changes", () => {
    const original = connectionToForm(sampleConnection);
    expect(isFormDirty(connectionToForm(sampleConnection), original)).toBe(false);
    expect(isFormDirty({ ...original, lifecycleStatus: "disabled" }, original)).toBe(true);
  });

  test("service form round-trips and trims into the patch payload", () => {
    const service = {
      service: "xero",
      name: "Xero",
      description: "Accounting",
      category: "finance",
      logo: null,
      connections: [sampleConnection],
    };
    const form = serviceToForm(service);
    expect(form.logo).toBe("");
    expect(isFormDirty(serviceToForm(service), form)).toBe(false);
    const payload = buildServicePayload({ ...form, name: "  Xero Books  ", logo: "  " });
    expect(payload.name).toBe("Xero Books");
    expect(payload.logo).toBeNull();
  });

  test("labels credential strategies for the tab bar", () => {
    expect(strategyLabel("static")).toBe("Static credentials");
    expect(strategyLabel("dcr")).toBe("Dynamic registration");
  });

  test("buildConnectionPayload rejects non-primitive extra auth params", () => {
    const form = connectionToForm(sampleConnection);
    form.extraAuthParamsText = JSON.stringify({ prompt: { mode: "consent" } });
    expect(() => buildConnectionPayload(form)).toThrow("must be a string, number, or boolean");
  });

  test("rejects invalid JSON object fields", () => {
    expect(() => parseJsonObject("[1]", "Runtime config")).toThrow("JSON object");
    expect(() => parseJsonObject("{", "Extra auth params")).toThrow("valid JSON");
    expect(parseJsonObject("", "Runtime config")).toEqual({});
  });
});

