import { describe, expect, test } from "vitest";
import { bundledIntegrationLogo } from "./integration-logos";

describe("bundledIntegrationLogo", () => {
  test("resolves known integration ids", () => {
    // Vitest/Vite may inline SVGs as data: URLs; match case-insensitively.
    expect(bundledIntegrationLogo("mercury")?.toLowerCase()).toContain("mercury");
    expect(bundledIntegrationLogo("Mercury")?.toLowerCase()).toContain("mercury");
    expect(bundledIntegrationLogo("agentuity")?.toLowerCase()).toContain("agentuity");
    expect(bundledIntegrationLogo("jobber")?.toLowerCase()).toContain("jobber");
    expect(bundledIntegrationLogo("google")?.toLowerCase()).toContain("google");
  });

  test("returns null for unknown ids", () => {
    expect(bundledIntegrationLogo("meta")).toBeNull();
    expect(bundledIntegrationLogo(undefined)).toBeNull();
  });
});

